                      'pytestmark = pytest.mark.cpu_test\n'
                      '\n'
                      '_SCOPE = "toolu_01AbCdEf"\n'
                      '\n'
                      '\n'
                      'def _minimal_payload(request_cls: type[BaseModel]) -> dict:\n'
                      '    """Smallest valid payload per protocol, before the identity '
                      'fields."""\n'
                      '    if request_cls is ChatCompletionRequest:\n'
                      '        return {"model": "m", "messages": [{"role": "user", '
                      '"content": "hi"}]}\n'
                      '    if request_cls is BatchChatCompletionRequest:\n'
                      '        return {"model": "m", "messages": [[{"role": "user", '
                      '"content": "hi"}]]}\n'
                      '    if request_cls is CompletionRequest:\n'
                      '        return {"model": "m", "prompt": "hi"}\n'
                      '    if request_cls is ResponsesRequest:\n'
                      '        return {"model": "m", "input": "hi"}\n'
                      '    if request_cls is AnthropicMessagesRequest:\n'
                      '        return {\n'
                      '            "model": "m",\n'
                      '            "max_tokens": 16,\n'
                      '            "messages": [{"role": "user", "content": "hi"}],\n'
                      '        }\n'
                      '    if request_cls is GenerateRequest:\n'
                      '        return {\n'
                      '            "request_id": "req-1",\n'
                      '            "token_ids": [1, 2, 3],\n'
                      '            "sampling_params": SamplingParams(),\n'
                      '        }\n'
                      '    raise AssertionError(f"unhandled protocol {request_cls}")\n'
                      '\n'
                      '\n'
                      'ALL_GENERATION_REQUESTS = [\n'
                      '    ChatCompletionRequest,\n'
                      '    BatchChatCompletionRequest,\n'
                      '    CompletionRequest,\n'
                      '    ResponsesRequest,\n'
                      '    AnthropicMessagesRequest,\n'
                      '    GenerateRequest,\n'
                      ']\n'
                      '\n'
                      '_OPENAI_SURFACES = [ChatCompletionRequest, CompletionRequest, '
                      'ResponsesRequest]\n'
                      '\n'
                      '\n'
                      'def _sampling_params_for(request):\n'
                      '    if isinstance(request, ResponsesRequest):\n'
                      '        return request.to_sampling_params(\n'
                      '            default_max_tokens=32, default_sampling_params={}\n'
                      '        )\n'
                      '    return request.to_sampling_params(max_tokens=32, '
                      'default_sampling_params={})\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("request_cls", '
                      'ALL_GENERATION_REQUESTS)\n'
                      'def test_every_surface_accepts_scope_fields(request_cls):\n'
                      '    request = request_cls(\n'
                      '        **_minimal_payload(request_cls),\n'
                      '        kv_scope=_SCOPE,\n'
                      '    )\n'
                      '    assert request.kv_scope == _SCOPE\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("request_cls", '
                      'ALL_GENERATION_REQUESTS)\n'
                      'def test_no_surface_invents_a_scope(request_cls):\n'
                      '    # A model may be built without one -- rendering shares '
                      'these models and\n'
                      '    # allocates nothing -- but no surface may fabricate an '
                      'identity to fill\n'
                      '    # the gap. What is absent here is refused later, at the '
                      'engine.\n'
                      '    request = request_cls(**_minimal_payload(request_cls))\n'
                      '    assert request.kv_scope is None\n'
                      '\n'
                      '\n'
