                      '    request = request_cls(**_minimal_payload(request_cls), '
                      'kv_scope=_SCOPE)\n'
                      '    assert require_kv_scope(_sampling_params_for(request)) == '
                      '_SCOPE\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("scope", ["", " ", "\\t\\n", 0, [], '
                      '{}, b"x"])\n'
                      'def '
                      'test_the_engine_refuses_a_scope_that_is_not_a_non_empty_string(scope):\n'
                      '    # Reaches the gate only through the direct SamplingParams '
                      'path; the\n'
                      '    # protocol models reject these earlier. Both doors are '
                      'shut.\n'
                      '    params = SamplingParams(max_tokens=1, '
                      'extra_args={"kv_scope": scope})\n'
                      '    with pytest.raises(VLLMValidationError) as excinfo:\n'
                      '        require_kv_scope(params)\n'
                      '    assert excinfo.value.parameter == "kv_scope"\n'
                      '\n'
                      '\n'
                      'def '
                      'test_a_batch_submits_every_conversation_under_the_one_agent():\n'
                      '    # One batch is one caller, so its conversations share the '
                      "caller's\n"
                      '    # identity rather than each becoming an anonymous context.\n'
                      '    batch = BatchChatCompletionRequest(\n'
                      '        model="m",\n'
                      '        messages=[\n'
                      '            [{"role": "user", "content": "a"}],\n'
                      '            [{"role": "user", "content": "b"}],\n'
                      '        ],\n'
                      '        kv_scope=_SCOPE,\n'
                      '    )\n'
                      '    singles = [batch.to_chat_completion_request(m) for m in '
                      'batch.messages]\n'
                      '    assert [s.kv_scope for s in singles] == [_SCOPE, _SCOPE]\n'
                      '    assert require_kv_scope(_sampling_params_for(singles[0])) '
                      '== _SCOPE\n'
                      '\n'
                      '\n'
                      'def test_anthropic_translation_forwards_scope_fields():\n'
                      '    # Anthropic rides the chat pipeline; the translation must '
