                      '    request.kv_scope = "writer-agent"\n'
                      '    request.kv_transfer_params = None\n'
                      '    request.num_prompt_tokens = 34\n'
                      '    request.num_tokens = 34\n'
                      '    request.num_computed_tokens = 0\n'
