                      '    state.group_states[1].block_ids[:] = [0, 21]\n'
                      '    scheduler._build_partial_tail_store_jobs(SimpleNamespace(\n'
                      '        partial_tail_offloads={request.request_id: [(1, 99, '
                      '28)]},\n'
                      '    ))\n'
