                      '        num_scheduled_tokens={request.request_id: 28}, '
                      'finished_req_ids=(),\n'
                      '    ))\n'
                      '    for job in scheduler._jobs.values():\n'
                      '        scheduler.manager.complete_store(job.keys, '
                      'state.req_context)\n'
                      '    partial_keys = {\n'
                      '        make_offload_key(request.block_hashes[3], 0),\n'
                      '        make_offload_key(request.block_hashes[6], 0),\n'
                      '        make_offload_key(request.block_hashes[6], 1),\n'
                      '    }\n'
                      '    assert scheduler.manager._contexts[request.request_id].keys '
                      '== partial_keys\n'
                      '    assert set(scheduler.manager._blocks) == partial_keys\n'
                      '\n'
                      '    # The writer advances. Its previous immutable partial state '
                      'remains available\n'
                      '    # in spare capacity, so another agent can fork that shorter '
                      'prefix.\n'
                      '    scheduler._build_store_jobs(SimpleNamespace(\n'
                      '        num_scheduled_tokens={request.request_id: 32}, '
                      'finished_req_ids=(),\n'
