                      'partial_keys\n'
                      '\n'
                      '    incoming = ReqContext(req_id="new-request", '
                      'kv_scope="new-agent")\n'
                      '    keys = [make_offload_key(f"new{i}".encode(), 0) for i in '
                      'range(4)]\n'
                      '    scheduler.manager.retain_context(keys, incoming)\n'
                      '    incoming.prefix_content = {key: (key,) for key in keys}\n'
                      '    output = scheduler.manager.prepare_store(keys, incoming)\n'
                      '    assert output is not None\n'
                      '    assert request.kv_scope not in scheduler.manager._agents\n'
                      '    assert fork.kv_scope in scheduler.manager._agents\n'
