                             '    state.update_offload_keys()\n'
                             '    state.group_states[0].block_ids[:] = [1, 2, 3, 4, 5, '
                             '6]\n'
                             '    state.group_states[1].block_ids[:] = [0, 12, 13, 14, '
                             '15, 16]\n'
