                       '    # Empty manager (4 blocks, none allocated): usage = 0.0\n'
                       '    manager = make_cpu_manager(num_blocks=4)\n'
                       '    check_usage_stats(manager, 0.0)\n'
                       '\n'
                       '    # After allocating 2 of 4 blocks: usage = 0.5\n'
                       '    manager.prepare_store(to_keys([1, 2]), _EMPTY_REQ_CTX)\n'
                       '    check_usage_stats(manager, 0.5)\n'
                       '\n'
                       '    # After filling all 4 blocks: usage = 1.0\n'
                       '    manager.prepare_store(to_keys([3, 4]), _EMPTY_REQ_CTX)\n'
                       '    check_usage_stats(manager, 1.0)\n'
                       '\n'
                       '    # After completing store, the blocks becomes evictable as '
                       'it is not actively used\n'
                       '    # and usage drops.\n'
                       '    manager.complete_store(to_keys([1, 2]), _EMPTY_REQ_CTX)\n'
                       '    check_usage_stats(manager, 0.5)\n'
                       '\n'
                       '    # After completing store, the blocks becomes evictable as '
                       'it is not actively used\n'
                       '    # and usage drops.\n'
                       '    manager.complete_store(to_keys([3, 4]), _EMPTY_REQ_CTX)\n'
                       '    check_usage_stats(manager, 0.0)\n'
                       '\n'
                       '\n'
                       'def test_cpu_manager_reports_allocation_size_histogram():\n'
                       '    manager = make_cpu_manager(num_blocks=4, '
                       'cache_policy="lru")\n'
                       '\n'
                       '    manager.prepare_store(to_keys([1, 2]), _EMPTY_REQ_CTX)\n'
                       '    manager.complete_store(to_keys([1, 2]), _EMPTY_REQ_CTX)\n'
                       '    manager.prepare_store(to_keys([1, 2, 3]), _EMPTY_REQ_CTX)\n'
                       '\n'
                       '    stats = manager.get_stats()\n'
                       '\n'
                       '    assert stats is not None\n'
                       '    reduced = stats.reduce()\n'
                       '    assert '
                       'reduced[f"{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_count"] '
                       '== 2\n'
                       '    assert '
                       'reduced[f"{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_sum"] == '
                       '3\n'
                       '\n'
                       '    # The cache-usage gauge is always reported, so get_stats() '
                       'never returns\n'
                       '    # None, but the histogram has nothing new once its samples '
                       'are consumed.\n'
                       '    second_stats = manager.get_stats()\n'
                       '    assert second_stats is not None\n'
                       '    assert f"{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_count" '
                       'not in (\n'
                       '        second_stats.reduce()\n'
                       '    )\n'
                       '\n'
                       '\n'
                       'def '
                       'test_cpu_manager_reports_allocation_size_on_allocation_failure(monkeypatch):\n'
                       '    manager = make_cpu_manager(num_blocks=4, '
                       'cache_policy="lru")\n'
                       '\n'
                       '    def fail_allocate_blocks(keys):\n'
                       '        raise RuntimeError("allocation failed")\n'
                       '\n'
                       '    monkeypatch.setattr(manager, "_allocate_blocks", '
                       'fail_allocate_blocks)\n'
                       '\n'
                       '    with pytest.raises(RuntimeError, match="allocation '
                       'failed"):\n'
                       '        manager.prepare_store(to_keys([1, 2, 3]), '
                       '_EMPTY_REQ_CTX)\n'
                       '\n'
                       '    stats = manager.get_stats()\n'
                       '\n'
                       '    assert stats is not None\n'
                       '    reduced = stats.reduce()\n'
