                       'reduced[f"{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_count"] '
                       '== 1\n'
                       '    assert '
                       'reduced[f"{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_sum"] == '
                       '3\n'
                       '\n'
                       '\n'
                       'def '
                       'test_cpu_manager_reports_allocation_size_on_eviction_failure():\n'
