                      '        keys = {bytes([k]) for k in rng.sample(range(30), '
                      'rng.randint(1, 8))}\n'
                      '        m.retain_context(keys, ctx)\n'
                      '        survivors = {\n'
                      '            req_id: set(c.keys) for req_id, c in '
                      'm._contexts.items()\n'
                      '            if c.keys <= m._blocks.keys()\n'
