                              'from collections import OrderedDict\n'
                              'from collections.abc import Iterable\n'
                              'from dataclasses import dataclass\n'
                              '\n'
                              'import numpy as np\n'
                              'import pytest\n'
                              '\n'
                              'from vllm.v1.kv_offload.base import (\n'
                              '    LoadStoreSpec,\n'
