                              'ARCCachePolicy\n'
                              '\n'
                              '\n'
                              'def make_req_context(\n'
                              '    req_id: str = "", kv_transfer_params: dict | None = '
                              'None\n'
                              ') -> ReqContext:\n'
                              '    """Create a ReqContext as production code would, '
                              'from a request\'s params."""\n'
                              '    return ReqContext(req_id=req_id, '
                              'kv_transfer_params=kv_transfer_params)\n'
                              '\n'
                              '\n'
                              '_EMPTY_REQ_CTX = make_req_context()\n'
                              '\n'
                              '\n'
                              'def make_cpu_manager(\n'
                              '    num_blocks: int = 4,\n'
                              '    cache_policy: str = "lru",\n'
                              '    cache_policy_module_path: str | None = None,\n'
                              '    enable_events: bool = False,\n'
                              '    store_threshold: int = 0,\n'
                              '    max_tracker_size: int = 64_000,\n'
                              ') -> CPUOffloadingManager:\n'
                              '    return CPUOffloadingManager(\n'
                              '        num_blocks=num_blocks,\n'
                              '        cache_policy=cache_policy,\n'
                              '        '
                              'cache_policy_module_path=cache_policy_module_path,\n'
                              '        enable_events=enable_events,\n'
                              '        store_threshold=store_threshold,\n'
                              '        max_tracker_size=max_tracker_size,\n'
                              '    )\n'
                              '\n'
                              '\n'
                              '@dataclass\n'
                              'class ExpectedPrepareStoreOutput:\n'
                              '    keys_to_store: list[int]\n'
                              '    store_block_ids: list[int]\n'
                              '    evicted_keys: list[int]\n'
                              '\n'
                              '\n'
                              'class _CountingOrderedDict(OrderedDict):\n'
                              '    def __init__(self, *args, **kwargs):\n'
                              '        super().__init__(*args, **kwargs)\n'
                              '        self.items_yielded = 0\n'
                              '\n'
                              '    def items(self):\n'
                              '        for item in super().items():\n'
                              '            self.items_yielded += 1\n'
                              '            yield item\n'
                              '\n'
                              '\n'
                              'def to_key(int_hash: int) -> OffloadKey:\n'
                              '    return make_offload_key(str(int_hash).encode(), 0)\n'
                              '\n'
                              '\n'
                              'def to_keys(int_hashes: list[int]) -> '
                              'list[OffloadKey]:\n'
                              '    return [to_key(i) for i in int_hashes]\n'
                              '\n'
                              '\n'
                              'def verify_store_output(\n'
                              '    prepare_store_output: PrepareStoreOutput | None,\n'
                              '    expected_prepare_store_output: '
                              'ExpectedPrepareStoreOutput,\n'
                              '):\n'
                              '    assert prepare_store_output is not None\n'
                              '    assert prepare_store_output.keys_to_store == '
                              'to_keys(\n'
                              '        expected_prepare_store_output.keys_to_store\n'
                              '    )\n'
                              '    assert prepare_store_output.evicted_keys == '
                              'to_keys(\n'
                              '        expected_prepare_store_output.evicted_keys\n'
                              '    )\n'
                              '    store_spec = prepare_store_output.store_spec\n'
                              '    assert isinstance(store_spec, CPULoadStoreSpec)\n'
                              '    expected_array = np.array(\n'
                              '        expected_prepare_store_output.store_block_ids, '
                              'dtype=np.int64\n'
                              '    )\n'
                              '    assert np.array_equal(expected_array, '
                              'store_spec.block_ids)\n'
                              '\n'
                              '\n'
                              'def verify_load_output(\n'
                              '    prepare_load_output: LoadStoreSpec, '
                              'expected_prepare_load_output: list[int]\n'
                              '):\n'
                              '    assert isinstance(prepare_load_output, '
                              'CPULoadStoreSpec)\n'
                              '    expected_array = '
                              'np.array(expected_prepare_load_output, dtype=np.int64)\n'
                              '    assert np.array_equal(expected_array, '
                              'prepare_load_output.block_ids)\n'
                              '\n'
                              '\n'
                              'def check_split_usage_stats(\n'
                              '    manager: CPUOffloadingManager, write: float, read: '
                              'float, total: float\n'
                              '):\n'
                              '    stats = manager.get_stats()\n'
                              '    assert stats is not None\n'
                              '    reduced = stats.reduce()\n'
                              '    assert '
                              'reduced[CPUOffloadingMetrics.CPU_CACHE_WRITE_USAGE_PERC] '
                              '== pytest.approx(\n'
                              '        write\n'
                              '    )\n'
                              '    assert '
                              'reduced[CPUOffloadingMetrics.CPU_CACHE_READ_USAGE_PERC] '
                              '== pytest.approx(\n'
                              '        read\n'
                              '    )\n'
                              '    assert '
                              'reduced[CPUOffloadingMetrics.CPU_CACHE_USAGE_PERC] == '
                              'pytest.approx(total)\n'
                              '\n'
                              '\n'
                              'def verify_events(\n'
                              '    events: Iterable[OffloadingEvent],\n'
                              '    expected_stores: tuple[set[int], ...] = (),\n'
                              '    expected_evictions: tuple[set[int], ...] = (),\n'
                              '):\n'
                              '    stores: list[set[OffloadKey]] = []\n'
                              '    evictions: list[set[OffloadKey]] = []\n'
                              '    for event in events:\n'
                              '        assert event.medium == Medium.CPU\n'
                              '        if event.removed:\n'
                              '            evictions.append(set(event.keys))\n'
                              '        else:\n'
                              '            stores.append(set(event.keys))\n'
                              '\n'
                              '    def to_key_sets(\n'
                              '        int_sets: tuple[set[int], ...],\n'
                              '    ) -> tuple[set[OffloadKey], ...]:\n'
                              '        return tuple([set(to_keys(list(int_set))) for '
                              'int_set in int_sets])\n'
                              '\n'
                              '    assert tuple(evictions) == '
                              'to_key_sets(expected_evictions)\n'
                              '    assert tuple(stores) == '
                              'to_key_sets(expected_stores)\n'
                              '\n'
                              '\n'
                              'def test_cpu_eviction_removed_precedes_stored():\n'
                              '    """An eviction is announced before the store that '
                              'reuses its capacity."""\n'
                              '    manager = make_cpu_manager(num_blocks=2, '
                              'enable_events=True)\n'
                              '\n'
                              '    manager.prepare_store(to_keys([1, 2]), '
                              '_EMPTY_REQ_CTX)\n'
                              '    manager.complete_store(to_keys([1, 2]), '
                              '_EMPTY_REQ_CTX)\n'
                              '    list(manager.take_events())\n'
                              '\n'
                              '    manager.prepare_store(to_keys([3]), '
                              '_EMPTY_REQ_CTX)\n'
                              '    manager.complete_store(to_keys([3]), '
                              '_EMPTY_REQ_CTX)\n'
                              '\n'
                              '    events = list(manager.take_events())\n'
                              '    removed_idx = [i for i, event in enumerate(events) '
                              'if event.removed]\n'
                              '    stored_idx = [i for i, event in enumerate(events) '
                              'if not event.removed]\n'
                              '    assert removed_idx and stored_idx, events\n'
                              '    assert max(removed_idx) < min(stored_idx)\n'
                              '    assert all(event.medium == manager.medium for event '
                              'in events)\n'
                              '\n'
                              '\n'
                              '@pytest.mark.parametrize("eviction_policy", ["lru", '
                              '"arc"])\n'
                              'def '
                              'test_already_stored_block_not_evicted_during_prepare_store(eviction_policy):\n'
                              '    """\n'
                              '    Regression test: a block that is already stored '
                              'must not be evicted\n'
                              '    by prepare_store() when it needs to make room for '
                              'new blocks.\n'
                              '    Applies to both lru and arc policies.\n'
                              '\n'
                              '    Scenario:\n'
                              '        - Store blocks [1, 2] and complete.\n'
                              '        - touch([1]) makes block 2 the LRU candidate.\n'
                              '        - prepare_store([2, 3, 4, 5]):\n'
                              '            * block 2 is filtered out as "already '
                              'stored"\n'
                              '            * but without the fix, block 2 would be '
                              'evicted as the LRU\n'
                              '              candidate to make room for [3, 4, 5]\n'
                              '        - After complete_store([2, 3, 4, 5]), block 2 '
                              'must still be present.\n'
                              '    """\n'
                              '    manager = make_cpu_manager(\n'
                              '        num_blocks=4,\n'
                              '        cache_policy=eviction_policy,\n'
                              '        enable_events=True,\n'
                              '    )\n'
                              '\n'
                              '    # store [1, 2] and complete\n'
                              '    manager.prepare_store(to_keys([1, 2]), '
                              '_EMPTY_REQ_CTX)\n'
                              '    manager.complete_store(to_keys([1, 2]), '
                              '_EMPTY_REQ_CTX)\n'
                              '\n'
                              '    # touch [1] to make block 2 the LRU candidate\n'
                              '    manager.touch(to_keys([1]), _EMPTY_REQ_CTX)\n'
                              '\n'
                              '    # prepare_store([2, 3, 4, 5]):\n'
                              '    #   - block 2 is already stored -> filtered out of '
                              'keys_to_store\n'
                              '    #   - block 2 must NOT be evicted even though it is '
                              'the LRU candidate\n'
                              '    #   - block 1 (ID 0) is evicted instead; new blocks '
                              '[3,4,5] get IDs 2,3,0\n'
                              '    prepare_store_output = '
                              'manager.prepare_store(to_keys([2, 3, 4, 5]), '
                              '_EMPTY_REQ_CTX)\n'
                              '    verify_store_output(\n'
                              '        prepare_store_output,\n'
                              '        ExpectedPrepareStoreOutput(\n'
                              '            keys_to_store=[3, 4, 5],\n'
                              '            store_block_ids=[2, 3, 0],\n'
                              '            evicted_keys=[1],  # block 1 evicted, not '
                              'block 2\n'
                              '        ),\n'
                              '    )\n'
                              '\n'
                              '    # complete_store must not silently drop block 2\n'
                              '    manager.complete_store(to_keys([2, 3, 4, 5]), '
                              '_EMPTY_REQ_CTX)\n'
                              '\n'
                              '    # block 2 must still be present in the cache\n'
                              '    assert manager.lookup(to_key(2), _EMPTY_REQ_CTX) is '
                              'LookupResult.HIT\n'
                              '\n'
                              '\n'
                              'def '
                              'test_filter_reused_manager_reports_stores_skipped_counter():\n'
                              '    manager = make_cpu_manager(\n'
