                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_transfer_pins_survive_reference_eviction_and_finish_independently():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    a, b = map(context, ['a', 'b'])\n"
                             "    store(m, a, [b'a', b'b', b'c'])\n"
                             "    slot = m._blocks[b'a'].block_id\n"
                             "    load(m, [b'a'], a)\n"
                             "    store(m, b, [b'x', b'y'])\n"
                             "    assert 'a' not in m._agents\n"
                             "    assert m._blocks[b'a'].block_id == slot\n"
                             "    assert m._blocks[b'a'].ref_cnt == 1\n"
                             "    m.complete_load([b'a'], a)\n"
                             "    store(m, b, [b'x', b'y', b'z', b'w'])\n"
                             "    assert b'a' not in m._blocks\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_advancing_window_reclaims_old_state_without_evicting_another_agent():\n'
                             '    m = CPUOffloadingManager(6)\n'
                             "    a, b = map(context, ['a', 'b'])\n"
                             "    store(m, a, [b'p', b'old-state'])\n"
                             "    store(m, b, [b'q', b'other-state'])\n"
                             "    store(m, a, [b'p', b'p2', b'new-state'])\n"
                             "    store(m, a, [b'p', b'p2', b'p3', b'latest-state'])\n"
                             "    assert set(m._agents) == {'a', 'b'}\n"
                             "    assert lookup(m, b'q', b) is LookupResult.HIT\n"
                             "    assert lookup(m, b'other-state', b) is "
                             'LookupResult.HIT\n'
                             "    assert not {b'old-state', b'new-state'} & "
                             'm._blocks.keys()\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_finished_context_is_retained_and_new_turn_replaces_it():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    first, second = context('a', 'first'), context('a', "
                             "'second')\n"
                             "    store(m, first, [b'old-prefix', b'old-state'])\n"
                             '    m.on_request_finished(first)\n'
                             '    assert first.req_id in m._contexts\n'
                             '    assert m.on_new_request(second).policy == '
                             'OffloadPolicy.REQUEST_LEVEL\n'
                             '    m.retain_context([], second)\n'
                             '    assert first.req_id in m._contexts\n'
                             "    store(m, second, [b'new-prefix', b'new-state'])\n"
                             '    assert first.req_id not in m._contexts\n'
