                      '\n'
                      '@pytest.mark.parametrize("world_size", [2, 4, 8])\n'
                      'def '
                      'test_cpu_spec_replicated_sizing_on_shared_region(monkeypatch, '
                      'world_size: int):\n'
                      '    # On shared-region (CUDA-alike) platforms the default spec '
                      'now honors\n'
                      '    # replicated layout: a single MLA copy (num_copies=1), '
                      'matching tiering.\n'
                      '    import vllm.v1.kv_offload.cpu.spec as cpu_spec_module\n'
                      '\n'
                      '    monkeypatch.setattr(cpu_spec_module.current_platform, '
                      '"is_cuda_alike", lambda: True)\n'
                      '    worker_kv_bytes_per_block = '
                      'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                      '    spec = _create_spec(\n'
                      '        worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                      '        world_size=world_size,\n'
                      '        replicated_layout=True,\n'
                      '    )\n'
                      '\n'
                      '    assert isinstance(spec, CPUOffloadingSpec)\n'
                      '    assert spec.replicated_layout is True\n'
                      '    assert spec.cpu_page_size_per_worker == '
                      'worker_kv_bytes_per_block\n'
                      '    assert spec.kv_bytes_per_chunk == '
                      'worker_kv_bytes_per_block\n'
                      '    assert spec.num_blocks == 8\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("world_size", [2, 4, 8])\n'
                      'def test_cpu_spec_replicated_disabled_without_shared_region(\n'
                      '    monkeypatch, world_size: int\n'
                      '):\n'
                      '    # Data-loss guard: non-CUDA-alike platforms keep a per-rank '
                      'private pinned\n'
                      '    # tensor (no shared medium), so replicated layout MUST stay '
                      'off. Otherwise\n'
                      '    # the rank-0 writer gate would ack rank>0 stores without '
                      'writing, leaving\n'
                      '    # those private buffers empty and corrupting subsequent '
                      'loads.\n'
                      '    import vllm.v1.kv_offload.cpu.spec as cpu_spec_module\n'
                      '\n'
                      '    monkeypatch.setattr(\n'
                      '        cpu_spec_module.current_platform, "is_cuda_alike", '
                      'lambda: False\n'
                      '    )\n'
                      '    worker_kv_bytes_per_block = '
                      'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                      '    spec = _create_spec(\n'
                      '        worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                      '        world_size=world_size,\n'
                      '        replicated_layout=True,\n'
                      '    )\n'
                      '\n'
                      '    assert isinstance(spec, CPUOffloadingSpec)\n'
                      '    assert spec.replicated_layout is False\n'
                      '    assert spec.cpu_page_size_per_worker == '
                      'worker_kv_bytes_per_block\n'
                      '    assert spec.kv_bytes_per_chunk == worker_kv_bytes_per_block '
                      '* world_size\n'
                      '    # Capacity is a chunk count (8 per declared user for '
                      '128/16), unchanged\n'
                      '    # by how many per-rank copies each chunk carries.\n'
                      '    assert spec.num_blocks == 8\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("config_replicated", [True, False])\n'
                      '@pytest.mark.parametrize("cuda_alike", [True, False])\n'
                      'def test_cpu_spec_replicated_layout_truth_matrix(\n'
                      '    monkeypatch, cuda_alike: bool, config_replicated: bool\n'
                      '):\n'
                      '    # replicated_layout is enabled iff the config gate passes '
                      'AND the deployment\n'
                      '    # actually allocates on the shared region (CUDA-alike).\n'
                      '    import vllm.v1.kv_offload.cpu.spec as cpu_spec_module\n'
                      '\n'
                      '    monkeypatch.setattr(\n'
                      '        cpu_spec_module.current_platform, "is_cuda_alike", '
                      'lambda: cuda_alike\n'
                      '    )\n'
                      '    worker_kv_bytes_per_block = '
                      'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                      '    spec = _create_spec(\n'
                      '        worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                      '        world_size=4,\n'
                      '        replicated_layout=config_replicated,\n'
                      '    )\n'
                      '\n'
                      '    assert isinstance(spec, CPUOffloadingSpec)\n'
                      '    assert spec.replicated_layout is (cuda_alike and '
                      'config_replicated)\n'
                      '\n'
                      '\n'
                      'def '
                      'test_cpu_spec_create_worker_uses_mmap_on_cuda_alike(monkeypatch):\n'
