                              '    data_parallel_size: int = 1,\n'
                              '    data_parallel_rank_local: int | None = None,\n'
                              '    is_parallelism_agnostic: bool = False,\n'
                              '    replicated_layout: bool = False,\n'
                              '    extra_config: dict[str, Any] | None = None,\n'
                              ') -> OffloadingConfig:\n'
                              '    normalized_extra_config = dict(extra_config or {})\n'
                              '    if spec_name is not None:\n'
                              '        normalized_extra_config["spec_name"] = '
                              'spec_name\n'
                              '    if cpu_bytes_to_use is not None:\n'
                              '        normalized_extra_config["cpu_bytes_to_use"] = '
                              'cpu_bytes_to_use\n'
                              '\n'
                              '    if groups is None:\n'
                              '        groups = (OffloadingGroupConfig(16, '
                              '("layer",)),)\n'
                              '\n'
                              '    return OffloadingConfig(\n'
                              '        groups=groups,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        enable_kv_cache_events=False,\n'
                              '        extra_config=normalized_extra_config,\n'
                              '        engine_id="test-engine",\n'
                              '        model=OffloadingModelConfig(name="test-model", '
                              'dtype="float16"),\n'
                              '        cache=OffloadingCacheConfig(\n'
                              '            tokens_per_hash=tokens_per_hash,\n'
                              '            blocks_per_chunk=blocks_per_chunk,\n'
                              '        ),\n'
                              '        parallel=OffloadingParallelConfig(\n'
                              '            rank=rank,\n'
                              '            world_size=world_size,\n'
                              '            tp_size=world_size if tp_size is None else '
                              'tp_size,\n'
                              '            pp_size=pp_size,\n'
                              '            pcp_size=pcp_size,\n'
                              '            dcp_size=dcp_size,\n'
                              '            data_parallel_index=data_parallel_index,\n'
                              '            data_parallel_size=data_parallel_size,\n'
                              '            '
                              'data_parallel_rank_local=data_parallel_rank_local,\n'
                              '            '
                              'is_parallelism_agnostic=is_parallelism_agnostic,\n'
                              '        ),\n'
                              '        replicated_layout=replicated_layout,\n'
                              '    )\n'
                              '\n'
                              '\n'
                              'def _create_spec(**kwargs: Any) -> OffloadingSpec:\n'
                              '    return '
                              'OffloadingSpecFactory.create_spec(_make_offloading_config(**kwargs))\n'
                              '\n'
                              '\n'
                              'class SingleArgExternalOffloadingSpec(OffloadingSpec):\n'
                              '    def get_manager(self) -> OffloadingManager:\n'
                              '        raise NotImplementedError\n'
                              '\n'
                              '    def get_worker(self, kv_caches: CanonicalKVCaches) '
                              '-> OffloadingWorker:\n'
                              '        raise NotImplementedError\n'
                              '\n'
                              '\n'
                              'def test_pre_registered_specs_can_be_imported():\n'
                              '    for name in OffloadingSpecFactory._registry:\n'
                              '        cls = OffloadingSpecFactory._registry[name]()\n'
                              '        assert issubclass(cls, OffloadingSpec)\n'
                              '\n'
                              '\n'
                              'def test_cpu_spec_registered():\n'
                              '    cls = '
                              'OffloadingSpecFactory._registry["CPUOffloadingSpec"]()\n'
                              '    assert cls is CPUOffloadingSpec\n'
                              '\n'
                              '\n'
                              'def test_tiering_spec_registered():\n'
                              '    cls = '
                              'OffloadingSpecFactory._registry["TieringOffloadingSpec"]()\n'
                              '    assert cls is TieringOffloadingSpec\n'
                              '\n'
                              '\n'
                              'def test_get_spec_cls_returns_registered_class():\n'
                              '    spec_cls = OffloadingSpecFactory.get_spec_cls(\n'
                              '        _make_offloading_config().extra_config\n'
                              '    )\n'
                              '    assert spec_cls is CPUOffloadingSpec\n'
                              '\n'
                              '\n'
                              'def test_get_spec_cls_defaults_to_cpu():\n'
                              '    spec_cls = OffloadingSpecFactory.get_spec_cls(\n'
                              '        '
                              '_make_offloading_config(spec_name=None).extra_config\n'
                              '    )\n'
                              '    assert spec_cls is CPUOffloadingSpec\n'
                              '\n'
                              '\n'
                              'def test_create_cpu_offloading_spec():\n'
                              '    spec = _create_spec()\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.num_blocks > 0\n'
                              '\n'
                              '\n'
                              'def test_cpu_spec_sizes_normalized_worker_layout():\n'
                              '    # The CPU spec now rounds the offloaded row up to '
                              'the mmap page size\n'
                              '    # (matching the shared region), so '
                              'kv_bytes_per_chunk picks up padding\n'
                              '    # while cpu_page_size_per_worker stays the '
                              'un-padded per-worker slot.\n'
                              '    alignment = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        cpu_bytes_to_use=alignment * 3,\n'
                              '        worker_kv_bytes_per_block=16,\n'
                              '        blocks_per_chunk=2,\n'
                              '        world_size=6,\n'
                              '        tp_size=3,\n'
                              '        pp_size=2,\n'
                              '    )\n'
                              '\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.cpu_page_size_per_worker == 32\n'
                              '    assert spec.kv_bytes_per_chunk == alignment\n'
                              '    assert spec.num_blocks == 3\n'
                              '\n'
                              '\n'
                              'def '
                              'test_cpu_spec_zero_worker_bytes_produces_empty_cache():\n'
                              '    spec = _create_spec(worker_kv_bytes_per_block=0, '
                              'world_size=4)\n'
                              '\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.cpu_page_size_per_worker == 0\n'
                              '    assert spec.kv_bytes_per_chunk == 0\n'
                              '    assert spec.num_blocks == 0\n'
                              '\n'
                              '\n'
                              'def test_tiering_spec_aligns_row_size():\n'
                              '    alignment = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        spec_name="TieringOffloadingSpec",\n'
                              '        cpu_bytes_to_use=alignment * 3,\n'
                              '        worker_kv_bytes_per_block=16,\n'
                              '        blocks_per_chunk=2,\n'
                              '        world_size=6,\n'
                              '        tp_size=3,\n'
                              '        pp_size=2,\n'
                              '    )\n'
                              '\n'
                              '    assert isinstance(spec, TieringOffloadingSpec)\n'
                              '    assert spec.cpu_page_size_per_worker == 32\n'
                              '    assert spec.kv_bytes_per_chunk == alignment\n'
                              '    assert spec.num_blocks == 3\n'
                              '\n'
                              '\n'
                              '@pytest.mark.parametrize("world_size", [2, 4, 8])\n'
                              'def '
                              'test_tiering_spec_replicated_sizing_removes_world_factor(world_size: '
                              'int):\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        spec_name="TieringOffloadingSpec",\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              '8,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=world_size,\n'
                              '        replicated_layout=True,\n'
                              '    )\n'
                              '\n'
                              '    assert isinstance(spec, TieringOffloadingSpec)\n'
                              '    assert spec.replicated_layout is True\n'
                              '    assert spec.cpu_page_size_per_worker == '
                              'worker_kv_bytes_per_block\n'
                              '    assert spec.kv_bytes_per_chunk == '
                              'worker_kv_bytes_per_block\n'
                              '    assert spec.num_blocks == 8\n'
                              '\n'
                              '\n'
                              'def '
                              'test_tiering_spec_create_worker_uses_single_slot_for_replicated_layout(monkeypatch):\n'
                              '    import vllm.v1.kv_offload.tiering.spec as '
                              'tiering_spec_module\n'
                              '\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        spec_name="TieringOffloadingSpec",\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              '8,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=4,\n'
                              '        replicated_layout=True,\n'
                              '    )\n'
                              '    assert isinstance(spec, TieringOffloadingSpec)\n'
                              '\n'
                              '    region = MagicMock()\n'
                              '    region_calls: list[dict[str, Any]] = []\n'
                              '    worker_calls: list[dict[str, Any]] = []\n'
                              '\n'
                              '    def fake_region_ctor(**kwargs):\n'
                              '        region_calls.append(kwargs)\n'
                              '        return region\n'
                              '\n'
                              '    def fake_worker_ctor(**kwargs):\n'
                              '        worker_calls.append(kwargs)\n'
                              '        return MagicMock()\n'
                              '\n'
                              '    monkeypatch.setattr(tiering_spec_module, '
                              '"SharedOffloadRegion", fake_region_ctor)\n'
                              '    monkeypatch.setattr(tiering_spec_module, '
                              '"CPUOffloadingWorker", fake_worker_ctor)\n'
                              '    monkeypatch.setattr(\n'
                              '        tiering_spec_module.torch.accelerator, '
                              '"current_device_index", lambda: 5\n'
                              '    )\n'
                              '\n'
                              '    kv_caches = MagicMock()\n'
                              '    spec.create_worker(kv_caches)\n'
                              '\n'
                              '    assert region_calls[0]["rank"] == 0\n'
                              '    assert region_calls[0]["kv_bytes_per_block"] == '
                              'worker_kv_bytes_per_block\n'
                              '    assert worker_calls[0]["kv_caches"] is kv_caches\n'
                              '    assert worker_calls[0]["mmap_region"] is region\n'
                              '\n'
                              '\n'
                              'def '
                              'test_tiering_spec_create_worker_folds_device_index_for_sharded_layout(monkeypatch):\n'
                              '    import vllm.v1.kv_offload.tiering.spec as '
                              'tiering_spec_module\n'
                              '\n'
                              '    spec = _create_spec(\n'
                              '        spec_name="TieringOffloadingSpec",\n'
                              '        worker_kv_bytes_per_block=4096,\n'
                              '        world_size=4,\n'
                              '    )\n'
                              '    assert isinstance(spec, TieringOffloadingSpec)\n'
                              '\n'
                              '    region_calls: list[dict[str, Any]] = []\n'
                              '\n'
                              '    def fake_region_ctor(**kwargs):\n'
                              '        region_calls.append(kwargs)\n'
                              '        return MagicMock()\n'
                              '\n'
                              '    monkeypatch.setattr(tiering_spec_module, '
                              '"SharedOffloadRegion", fake_region_ctor)\n'
                              '    monkeypatch.setattr(tiering_spec_module, '
                              '"CPUOffloadingWorker", MagicMock())\n'
                              '    monkeypatch.setattr(\n'
                              '        tiering_spec_module.torch.accelerator,\n'
                              '        "current_device_index",\n'
                              '        lambda: 5,\n'
                              '    )\n'
                              '\n'
                              '    spec.create_worker(MagicMock())\n'
                              '\n'
                              '    assert region_calls[0]["rank"] == 1\n'
                              '\n'
                              '\n'
                              '@pytest.mark.parametrize("world_size", [2, 4, 8])\n'
                              'def '
                              'test_cpu_spec_replicated_sizing_on_shared_region(monkeypatch, '
                              'world_size: int):\n'
                              '    # On shared-region (CUDA-alike) platforms the '
                              'default spec now honors\n'
                              '    # replicated layout: a single MLA copy '
                              '(num_copies=1), matching tiering.\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    '
                              'monkeypatch.setattr(cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: True)\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              '8,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=world_size,\n'
                              '        replicated_layout=True,\n'
                              '    )\n'
                              '\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.replicated_layout is True\n'
                              '    assert spec.cpu_page_size_per_worker == '
                              'worker_kv_bytes_per_block\n'
                              '    assert spec.kv_bytes_per_chunk == '
                              'worker_kv_bytes_per_block\n'
                              '    assert spec.num_blocks == 8\n'
                              '\n'
                              '\n'
                              '@pytest.mark.parametrize("world_size", [2, 4, 8])\n'
                              'def '
                              'test_cpu_spec_replicated_disabled_without_shared_region(\n'
                              '    monkeypatch, world_size: int\n'
                              '):\n'
                              '    # Data-loss guard: non-CUDA-alike platforms keep a '
                              'per-rank private pinned\n'
                              '    # tensor (no shared medium), so replicated layout '
                              'MUST stay off. Otherwise\n'
                              '    # the rank-0 writer gate would ack rank>0 stores '
                              'without writing, leaving\n'
                              '    # those private buffers empty and corrupting '
                              'subsequent loads.\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: False\n'
                              '    )\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              'world_size * 2,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=world_size,\n'
                              '        replicated_layout=True,\n'
                              '    )\n'
                              '\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.replicated_layout is False\n'
                              '    assert spec.cpu_page_size_per_worker == '
                              'worker_kv_bytes_per_block\n'
                              '    assert spec.kv_bytes_per_chunk == '
                              'worker_kv_bytes_per_block * world_size\n'
                              '    assert spec.num_blocks == 2\n'
                              '\n'
                              '\n'
                              '@pytest.mark.parametrize("config_replicated", [True, '
                              'False])\n'
                              '@pytest.mark.parametrize("cuda_alike", [True, False])\n'
                              'def test_cpu_spec_replicated_layout_truth_matrix(\n'
                              '    monkeypatch, cuda_alike: bool, config_replicated: '
                              'bool\n'
                              '):\n'
                              '    # replicated_layout is enabled iff the config gate '
                              'passes AND the deployment\n'
                              '    # actually allocates on the shared region '
                              '(CUDA-alike).\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: cuda_alike\n'
                              '    )\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              '8,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=4,\n'
                              '        replicated_layout=config_replicated,\n'
                              '    )\n'
                              '\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.replicated_layout is (cuda_alike and '
                              'config_replicated)\n'
                              '\n'
                              '\n'
                              'def '
                              'test_cpu_spec_create_worker_uses_mmap_on_cuda_alike(monkeypatch):\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              '8,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=4,\n'
                              '    )\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '\n'
                              '    region = MagicMock()\n'
                              '    region_calls: list[dict[str, Any]] = []\n'
                              '    worker_calls: list[dict[str, Any]] = []\n'
                              '\n'
                              '    def fake_region_ctor(**kwargs):\n'
                              '        region_calls.append(kwargs)\n'
                              '        return region\n'
                              '\n'
                              '    def fake_worker_ctor(**kwargs):\n'
                              '        worker_calls.append(kwargs)\n'
                              '        return MagicMock()\n'
                              '\n'
                              '    '
                              'monkeypatch.setattr(cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: True)\n'
                              '    monkeypatch.setattr(cpu_spec_module, '
                              '"SharedOffloadRegion", fake_region_ctor)\n'
                              '    monkeypatch.setattr(cpu_spec_module, '
                              '"CPUOffloadingWorker", fake_worker_ctor)\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module.torch.accelerator, '
                              '"current_device_index", lambda: 5\n'
                              '    )\n'
                              '\n'
                              '    kv_caches = MagicMock()\n'
                              '    spec.create_worker(kv_caches)\n'
                              '\n'
                              '    assert region_calls[0]["engine_id"] == '
                              '"test-engine"\n'
                              '    assert region_calls[0]["kv_bytes_per_block"] == '
                              'worker_kv_bytes_per_block * 4\n'
                              '    assert worker_calls[0]["kv_caches"] is kv_caches\n'
                              '    assert worker_calls[0]["mmap_region"] is region\n'
                              '\n'
                              '\n'
                              'def '
                              'test_cpu_spec_create_worker_uses_tensor_path_off_cuda_alike(monkeypatch):\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    spec = _create_spec(worker_kv_bytes_per_block=4096, '
                              'world_size=4)\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '\n'
                              '    region_calls: list[dict[str, Any]] = []\n'
                              '    worker_calls: list[dict[str, Any]] = []\n'
                              '\n'
                              '    def fake_region_ctor(**kwargs):\n'
                              '        region_calls.append(kwargs)\n'
                              '        return MagicMock()\n'
                              '\n'
                              '    def fake_worker_ctor(**kwargs):\n'
                              '        worker_calls.append(kwargs)\n'
                              '        return MagicMock()\n'
                              '\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: False\n'
                              '    )\n'
                              '    monkeypatch.setattr(cpu_spec_module, '
                              '"SharedOffloadRegion", fake_region_ctor)\n'
                              '    monkeypatch.setattr(cpu_spec_module, '
                              '"CPUOffloadingWorker", fake_worker_ctor)\n'
                              '\n'
                              '    spec.create_worker(MagicMock())\n'
                              '\n'
                              '    # Non-CUDA-alike platforms keep the per-rank '
                              'pinned-tensor path.\n'
                              '    assert region_calls == []\n'
                              '    assert worker_calls[0]["mmap_region"] is None\n'
                              '\n'
                              '\n'
                              'def '
                              'test_cpu_spec_create_worker_skips_mmap_for_empty_cache(monkeypatch):\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    # worker_kv_bytes_per_block=0 yields num_blocks=0; '
                              'a zero-byte region cannot\n'
                              "    # be mmap'd, so even on CUDA-alike this must fall "
                              'back to the tensor path.\n'
                              '    spec = _create_spec(worker_kv_bytes_per_block=0, '
                              'world_size=4)\n'
                              '    assert isinstance(spec, CPUOffloadingSpec)\n'
                              '    assert spec.num_blocks == 0\n'
                              '\n'
                              '    region_calls: list[dict[str, Any]] = []\n'
                              '    worker_calls: list[dict[str, Any]] = []\n'
                              '\n'
                              '    '
                              'monkeypatch.setattr(cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: True)\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module,\n'
                              '        "SharedOffloadRegion",\n'
                              '        lambda **kwargs: region_calls.append(kwargs),\n'
                              '    )\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module,\n'
                              '        "CPUOffloadingWorker",\n'
                              '        lambda **kwargs: worker_calls.append(kwargs),\n'
                              '    )\n'
                              '\n'
                              '    spec.create_worker(MagicMock())\n'
                              '\n'
                              '    assert region_calls == []\n'
                              '    assert worker_calls[0]["mmap_region"] is None\n'
                              '\n'
                              '\n'
                              '@pytest.mark.parametrize(\n'
                              '    ("replicated_layout", "device_index", "world_size", '
                              '"expected_rank"),\n'
                              '    [\n'
                              '        (True, 5, 4, 0),  # replicated: always slot 0\n'
                              '        (True, 0, 4, 0),  # replicated: slot 0 '
                              'regardless of device\n'
                              '        (False, 5, 4, 1),  # non-replicated: 5 % 4 == '
                              '1\n'
                              '        (False, 7, 4, 3),  # non-replicated: 7 % 4 == '
                              '3\n'
                              '    ],\n'
                              ')\n'
                              'def test_cpu_spec_create_worker_rank_assignment(\n'
                              '    monkeypatch, replicated_layout, device_index, '
                              'world_size, expected_rank\n'
                              '):\n'
                              '    import vllm.v1.kv_offload.cpu.spec as '
                              'cpu_spec_module\n'
                              '\n'
                              '    '
                              'monkeypatch.setattr(cpu_spec_module.current_platform, '
                              '"is_cuda_alike", lambda: True)\n'
                              '    worker_kv_bytes_per_block = '
                              'SharedOffloadRegion.BLOCK_SIZE_ALIGNMENT\n'
                              '    spec = _create_spec(\n'
                              '        cpu_bytes_to_use=worker_kv_bytes_per_block * '
                              '8,\n'
                              '        '
                              'worker_kv_bytes_per_block=worker_kv_bytes_per_block,\n'
                              '        world_size=world_size,\n'
                              '        replicated_layout=replicated_layout,\n'
                              '    )\n'
                              '\n'
                              '    region_calls: list[dict[str, Any]] = []\n'
