                              '    monkeypatch.setattr(cpu_spec_module, '
                              '"SharedOffloadRegion", fake_region_ctor)\n'
                              '    monkeypatch.setattr(cpu_spec_module, '
                              '"CPUOffloadingWorker", MagicMock())\n'
                              '    monkeypatch.setattr(\n'
                              '        cpu_spec_module.torch.accelerator, '
                              '"current_device_index", lambda: device_index\n'
                              '    )\n'
                              '\n'
                              '    spec.create_worker(MagicMock())\n'
                              '\n'
                              '    assert region_calls[0]["rank"] == expected_rank\n'
                              '\n'
                              '\n'
                              'def '
                              'test_offloading_spec_has_replicated_layout_default():\n'
                              '    spec = '
                              'SingleArgExternalOffloadingSpec(_make_offloading_config())\n'
                              '    assert spec.replicated_layout is False\n'
