                      '0.0}).to_sampling_params(509, DEFAULTS)\n'
                      '    assert params.temperature == 0.0\n'
                      '    assert (params.top_p, params.top_k, params.min_p) == (1.0, '
                      '0, 0.0)\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("key", ["_eos_token_id", "skip_clone", '
                      '"output_text_buffer_length", "unknown"])\n'
                      'def test_engine_internal_fields_are_not_request_settings(key):\n'
                      '    with pytest.raises(ValidationError):\n'
                      '        generate({key: 1})\n'
                      '\n'
                      '\n'
                      'def '
                      'test_stop_ids_and_transport_metadata_survive_resolution_without_mutation():\n'
                      '    original = {"stop_token_ids": [7, 8], "extra_args": '
                      '{"custom": "value"}}\n'
                      '    request = generate(original)\n'
                      '    request.kv_transfer_params = {"remote": "kv"}\n'
                      '    request.ec_transfer_params = {"remote": "encoder"}\n'
                      '    defaults = {**DEFAULTS, "stop_token_ids": [8, 9]}\n'
                      '    params = request.to_sampling_params(509, defaults)\n'
                      '    assert params.stop_token_ids == [7, 8, 9]\n'
                      '    assert params.extra_args == {\n'
                      '        "custom": "value", "kv_scope": "agent", '
                      '"kv_transfer_params": {"remote": "kv"},\n'
                      '        "ec_transfer_params": {"remote": "encoder"},\n'
                      '    }\n'
                      '    assert original["extra_args"] == {"custom": "value"}\n'
                      '    assert defaults["stop_token_ids"] == [8, 9]\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
