                      '    serving.override_max_tokens = None\n'
                      '    serving.force_no_detokenize = False\n'
                      '    serving.enable_prompt_tokens_details = False\n'
                      '    serving.enable_log_outputs = False\n'
                      '    serving._check_model = AsyncMock(return_value=None)\n'
                      '    serving._maybe_get_adapters = MagicMock(return_value=None)\n'
