                      '    params.structured_outputs.json["properties"]["added"] = '
                      '{"type": "string"}\n'
                      '    assert request.model_dump_json() == before\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
                      '@pytest.mark.parametrize("surface", ["chat", "completion"])\n'
                      '@pytest.mark.parametrize("requested_max, expected_max", [(None, '
                      '509), (16, 16)])\n'
                      'async def '
                      'test_rendered_requests_keep_resolved_sampling_through_generate_json(\n'
                      '    surface, requested_max, expected_max,\n'
                      '):\n'
                      '    from types import SimpleNamespace\n'
                      '    from unittest.mock import AsyncMock\n'
                      '\n'
                      '    from vllm.entrypoints.scale_out.render.serving import '
