                      '\n'
                      '    render = object.__new__(ServingRender)\n'
                      '    render.model_config = SimpleNamespace(max_model_len=512, '
                      'is_encoder_decoder=False)\n'
                      '    render.default_sampling_params = dict(DEFAULTS)\n'
                      '    render.override_max_tokens = None\n'
                      '    render._check_model = AsyncMock(return_value=None)\n'
                      '    prompt = {"type": "token", "prompt_token_ids": [1, 2, 3]}\n'
                      '    render.online_renderer = SimpleNamespace(\n'
                      '        render_chat=AsyncMock(return_value=(None, [prompt])),\n'
                      '        render_completion=AsyncMock(return_value=[prompt]),\n'
