                      '    assert params.thinking_token_budget is None\n'
                      '    assert params.final_response_token_budget == 100\n'
                      '    assert params.extra_args["kv_scope"] == "agent"\n'
                      '\n'
                      '\n'
                      'def '
                      'test_sampling_schema_preserves_omission_and_exposes_only_request_inputs():\n'
                      '    schema = GenerateRequest.model_json_schema()\n'
                      '    sampling = schema["properties"]["sampling_params"]\n'
