                       '\n'
                       '\n'
                       'def test_mm_kwargs_item_nested_tensors():\n'
                       '    """Roundtrip with nested tensor data."""\n'
                       '    nested = [torch.randn(3, 4), torch.randn(5, 4)]\n'
                       '    elem = MultiModalFieldElem(\n'
                       '        data=nested,\n'
                       '        field=MultiModalBatchedField(),\n'
                       '    )\n'
                       '    item = MultiModalKwargsItem({"nested": elem})\n'
                       '    encoded = encode_mm_kwargs_item(item)\n'
                       '    decoded = decode_mm_kwargs_item(encoded)\n'
                       '\n'
                       '    decoded_data = decoded["nested"].data\n'
                       '    assert len(decoded_data) == 2\n'
                       '    assert torch.equal(nested[0], decoded_data[0])\n'
                       '    assert torch.equal(nested[1], decoded_data[1])\n'
                       '\n'
                       '\n'
                       'def test_mm_features_with_kwargs_data():\n'
                       '    """Test that MultiModalFeatures can carry serialized '
