                      '@pytest.mark.parametrize("value", ["HALT", "</tool_call> HALT '
                      '<tool_call>", "λ HALT"])\n'
                      'def test_structural_text_stop_keeps_the_call(chunk_size, '
                      'choice, value):\n'
                      '    from unittest.mock import MagicMock\n'
                      '    from vllm.v1.engine.detokenizer import '
                      'BaseIncrementalDetokenizer\n'
                      '    from vllm.v1.structured_output.stop_checker import '
                      'StructuralTagStopChecker\n'
                      '\n'
                      '    request = _tag_request(stop=["HALT"], choice=choice)\n'
                      '    body = CALL.format(value)\n'
                      '    output = body + (" after HALT discarded" if choice == '
                      '"auto" else "")\n'
                      '    pieces = [output[i:i + chunk_size] for i in range(0, '
                      'len(output), chunk_size)]\n'
                      '\n'
                      '    class TextDetokenizer(BaseIncrementalDetokenizer):\n'
                      '        def decode_next(self, token):\n'
                      '            return pieces[token]\n'
                      '\n'
                      '    detok = TextDetokenizer(request)\n'
                      '    detok.stop_checker = StructuralTagStopChecker(MagicMock(), '
                      'request, None)\n'
                      '    reason = None\n'
                      '    for token in range(len(pieces)):\n'
                      '        reason = detok.update([token], False)\n'
                      '        if reason:\n'
                      '            break\n'
                      '    assert reason == ("HALT" if choice == "auto" else None)\n'
                      '    assert detok.get_next_output_text(True, False) == (\n'
                      '        body + " after " if choice == "auto" else body\n'
                      '    )\n'
                      '\n'
