                      'StructuredOutputManager\n'
                      '\n'
                      '    engine_request = _tag_request(stop_token_ids=[ord("X")])\n'
                      '    request = Request.from_engine_core_request(engine_request, '
                      'block_hasher=None)\n'
                      '    vocabulary = [chr(i) for i in range(128)] + ["<eos>", '
                      '"<eos2>"]\n'
                      '    backend = XgrammarBackend.__new__(XgrammarBackend)\n'
                      '    backend.compiler = xgr.GrammarCompiler(\n'
                      '        xgr.TokenizerInfo(vocabulary, stop_token_ids=[128]), '
                      'max_threads=1\n'
                      '    )\n'
                      '    backend.vocab_size = len(vocabulary)\n'
                      '    backend.num_speculative_tokens = 0\n'
                      '    backend.disable_any_whitespace = False\n'
                      '    manager = '
                      'StructuredOutputManager.__new__(StructuredOutputManager)\n'
                      '    manager.backend = backend\n'
                      '    manager.reasoner_cls = None\n'
                      '    grammar = manager._create_grammar(request)\n'
                      '    request.structured_output_request.grammar = grammar\n'
                      '    request.status = RequestStatus.RUNNING\n'
                      '    scheduler = Scheduler.__new__(Scheduler)\n'
                      '    scheduler.structured_output_manager = manager\n'
                      '    scheduler.max_model_len = 4096\n'
                      '\n'
                      '    for char in CALL.format("X </tool_call> X"):\n'
                      '        bitmask = backend.allocate_token_bitmask(1)\n'
                      '        grammar.fill_bitmask(bitmask, 0)\n'
                      '        assert _token_allowed(bitmask[0], ord(char)), char\n'
                      '        tokens, stopped = '
                      'scheduler._update_request_with_output(request, [ord(char)])\n'
                      '        assert not stopped, char\n'
                      '        assert grammar.accept_tokens(request.request_id, '
                      'tokens)\n'
                      '    assert request.stop_reason is None\n'
                      '    _, stopped = scheduler._update_request_with_output(request, '
                      '[ord("X")])\n'
                      '    assert stopped\n'
                      '    assert request.stop_reason == ord("X")\n'
