                      '    params.output_kind = RequestOutputKind.DELTA if stream else '
                      'RequestOutputKind.FINAL_ONLY\n'
                      '    params.include_stop_str_in_output = include_stop\n'
                      '    params.update_from_generation_config({"eos_token_id": '
