                      'stop-buffer cuts."""\n'
                      '\n'
                      '    @staticmethod\n'
                      '    def _scanner():\n'
                      '        from types import SimpleNamespace\n'
                      '        from tokenizers import Tokenizer, decoders, models\n'
                      '\n'
                      '        vocabulary = {chr(i): i for i in range(33, 127)}\n'
                      '        vocabulary.update({"Ġ": 32, "é": 200, "Ľ": 201, "ª": '
                      '202,\n'
